@keyframes banner-slide {
  0%, 45.7% { transform: translateX(0); animation-timing-function: cubic-bezier(0.65, 0, 0.35, 1); }
  50% { transform: translateX(-100%); }
  50.01%, 95.7% { transform: translateX(100%); animation-timing-function: cubic-bezier(0.65, 0, 0.35, 1); }
  100% { transform: translateX(0); }
}
.banner-content,
.banner-content-next {
  animation: banner-slide 14s infinite;
}
.banner-content-next {
  animation-delay: -7s;
}
.banner-close:hover { opacity: 0.7; }
@media (prefers-reduced-motion: reduce) {
  .banner-content { animation: none; }
  .banner-content-next { display: none; }
}


(function () {
  document.addEventListener('click', function (e) {
    var btn = e.target.closest && e.target.closest('.banner-close');
    if (!btn) return;
    e.preventDefault();
    e.stopPropagation();
    document.documentElement.classList.remove('banner-open');
    try { sessionStorage.setItem('polycamBannerClosed', '1'); } catch (err) {}
  }, true);
})();
